from collections import Counter
from scipy import ndimage
def process(g_in):
    g=np.array(g_in); bg=Counter(g.flatten()).most_common(1)[0][0]
    lab,n=ndimage.label(g!=bg,structure=np.ones((3,3)))
    H,W=g.shape
    objs=[]; strays={}
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        cs=[int(g[y,x]) for y,x in zip(ys.tolist(),xs.tolist())]
        maj=Counter(cs).most_common(1)[0][0]
        if len(cs)>1:
            y0=min(ys); x0=min(xs)
            objs.append({'maj':maj,'cells':tuple(sorted(((y-y0,x-x0) for y,x in zip(ys.tolist(),xs.tolist())))),'size':len(cs)})
        else:
            y,x=int(np.argwhere(lab==i)[0]); 
            cnt=Counter(int(g[dy,dx]) for dy in(-1,0,1) for dx in(-1,0,1)
                       if (dy or dx) and 0<=y+dy<H and 0<=x+dx<W and int(g[y+dy,x+dx])!=bg)
            strays[(y,x)]=cnt.most_common(1)[0][0]
    # paint strays onto a fresh grid of bg
    out=np.full((H,W),bg,dtype=int)
    for (y,x),c in strays.items(): out[y,x]=c
    # greedy pack: sort objs by size desc, place at highest-left free spot
    objs.sort(key=lambda o:-o['size'])
    for mi,o in enumerate(objs):
        h=max(r for r,_ in o['cells'])+1; w=max(c for _,c in o['cells'])+1
        placed=False
        for dy in range(H-h+1):
            for dx in range(W-w+1):
                ok=True
                for r,c in o['cells']:
                    rd,cd=dy+r,dx+c
                    if out[rd,cd]!=bg: ok=False;break
                if ok:
                    for r,c in o['cells']: out[dy+r,dx+c]=o['maj']; placed=True;break
            if placed:break
    return out.tolist()
