for p in ['Demo pair 1','Demo pair 2','Demo pair 3','Demo pair 5','Demo pair 6']:
    pred=np.array(process(G[p+' input'])); o=np.array(G[p+' output'])
    print(p,'match:',np.array_equal(pred,o), pred.shape,o.shape)

