import collections
def comps(g,bg=8):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; pts=[]
                while st:
                    a,b=st.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; pts.append((a,b))
                    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+di,b+dj
                        if 0<=x<H and 0<=y<W and g[x][y]==col and not seen[x][y]: st.append((x,y))
                out.append((col,pts))
    return out
